import assert from 'node:assert/strict';

import { bookingHistory } from '../src/projections/history.ts';
import type { DomainEvent } from '../src/domain/events.ts';

function requested(over: Partial<any> = {}): DomainEvent {
  return {
    type: 'BookingRequested', bookingId: 'bk-1', occurredAt: '2026-08-03T00:00:00.000Z', actorId: 'u-pat',
    userId: 'u-pat', userRole: 'STUDENT', resourceId: 'gpu-a100-01',
    startAt: '2026-08-05T09:00:00.000Z', endAt: '2026-08-05T13:00:00.000Z', requiresApproval: false,
    ...over,
  } as DomainEvent;
}

describe('ประวัติเหตุการณ์ของการจอง (REQ-41)', () => {
  test('คืนเหตุการณ์เรียงตามเวลาที่เกิดขึ้น แม้บันทึกมาไม่เรียง', () => {
    const events: DomainEvent[] = [
      { type: 'BookingApproved', bookingId: 'bk-1', occurredAt: '2026-08-03T02:00:00.000Z', actorId: 'u-admin' },
      requested(),
      { type: 'BookingStarted', bookingId: 'bk-1', occurredAt: '2026-08-05T09:00:00.000Z', actorId: 'u-pat', actualStartAt: '2026-08-05T09:00:00.000Z' },
    ];

    const history = bookingHistory(events, 'bk-1');

    assert.deepEqual(history.map((e) => e.type), ['BookingRequested', 'BookingApproved', 'BookingStarted']);
  });

  test('ไม่รวมเหตุการณ์ของการจองรายการอื่น', () => {
    const events: DomainEvent[] = [
      requested(),
      requested({ bookingId: 'bk-2', occurredAt: '2026-08-03T01:00:00.000Z' }),
    ];

    const history = bookingHistory(events, 'bk-1');

    assert.equal(history.length, 1);
    assert.equal(history[0].bookingId, 'bk-1');
  });

  test('การจองที่ไม่มีเหตุการณ์เลย -> คืนอาเรย์ว่าง', () => {
    assert.deepEqual(bookingHistory([requested()], 'bk-unknown'), []);
  });
});

